import{_ as t,o,c as s,a2 as a}from"./chunks/framework.C1GzXyVk.js";const g=JSON.parse('{"title":"Glossary","description":"Definitions of key terms used in hookshot documentation","frontmatter":{"title":"Glossary","description":"Definitions of key terms used in hookshot documentation","audience":["evaluator","user","operator","developer","contributor","architect"]},"headers":[],"relativePath":"understand/glossary.md","filePath":"understand/glossary.md","lastUpdated":1775242895000}'),r={name:"understand/glossary.md"};function n(i,e,c,d,p,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><h2 id="hookshot-concepts" tabindex="-1">Hookshot concepts <a class="header-anchor" href="#hookshot-concepts" aria-label="Permalink to &quot;Hookshot concepts&quot;">​</a></h2><p><strong>Connection</strong> A binding between a Matrix room and an external resource. Stored as a Matrix room state event. Examples: a GitHub repo connection, a generic webhook, an RSS feed subscription. See <a href="./integration-model">Integration Model</a>.</p><p><strong>Connection type</strong> A class that implements the Connection interface for a specific service. Hookshot has 15 connection types across 8 services. Examples: <code>GitHubRepoConnection</code>, <code>GenericHookConnection</code>, <code>FeedConnection</code>.</p><p><strong>Inbound event</strong> An event originating from an external service (webhook, feed update) that hookshot delivers as a Matrix message.</p><p><strong>Outbound command</strong> A bot command sent by a user in a Matrix room that hookshot executes as an action on an external service. Example: <code>!gh create &quot;Bug title&quot;</code>.</p><p><strong>Transformation function</strong> User-supplied JavaScript code that transforms a generic webhook payload into a custom Matrix message. Runs in a QuickJS sandbox with a 500ms timeout.</p><p><strong>Hook / Webhook</strong> An HTTP endpoint that receives POST requests from external services. Each hookshot integration has its own webhook path (e.g., <code>/github/webhook</code>, <code>/webhook/{hookId}</code>).</p><p><strong>Outbound hook</strong> A connection that forwards Matrix room messages to an external HTTP endpoint (the reverse of a regular webhook).</p><p><strong>Service bot</strong> A Matrix user identity that hookshot uses to send messages. The default bot is <code>@hookshot:domain</code>. Additional service-specific bots can be configured (e.g., a dedicated GitHub bot).</p><h2 id="matrix-concepts" tabindex="-1">Matrix concepts <a class="header-anchor" href="#matrix-concepts" aria-label="Permalink to &quot;Matrix concepts&quot;">​</a></h2><p><strong>Application service (appservice)</strong> A privileged service that registers with a Matrix homeserver. Hookshot is an appservice. Appservices can impersonate users, receive all events in rooms they join, and reserve user ID namespaces. See <a href="https://spec.matrix.org/latest/application-service-api/" target="_blank" rel="noreferrer">Matrix Spec</a>.</p><p><strong>Homeserver</strong> The Matrix server that stores rooms, events, and user accounts. Examples: Synapse, Dendrite, Conduit. Hookshot connects to a homeserver via the appservice API.</p><p><strong>Room state event</strong> A Matrix event with a <code>type</code> and <code>state_key</code> that represents persistent configuration in a room. Hookshot uses custom state event types (e.g., <code>uk.half-shot.matrix-hookshot.github.repository</code>) to store connection configuration. See <a href="https://spec.matrix.org/latest/client-server-api/#room-state" target="_blank" rel="noreferrer">Matrix Spec</a>.</p><p><strong>Intent</strong> A Matrix SDK concept. An intent represents a virtual user that the appservice can act as. Hookshot uses intents to send messages as bot users.</p><p><strong>m.room.message</strong> The standard Matrix event type for messages. Hookshot sends notifications as <code>m.room.message</code> events with <code>msgtype: m.notice</code> (to distinguish bot messages from human messages).</p><p><strong>m.notice</strong> A message type indicating a bot/automated message. Matrix clients typically render these differently (e.g., gray text in Element).</p><h2 id="infrastructure-concepts" tabindex="-1">Infrastructure concepts <a class="header-anchor" href="#infrastructure-concepts" aria-label="Permalink to &quot;Infrastructure concepts&quot;">​</a></h2><p><strong>Bridge</strong> In Matrix terminology, a bridge connects Matrix to another communication platform. Hookshot is technically an appservice that acts as a bridge to multiple services.</p><p><strong>NAPI / NAPI-rs</strong> Node.js API for native addons. Hookshot uses NAPI-rs to call Rust code from TypeScript for performance-critical operations (feed parsing, token encryption, permission checking).</p><p><strong>QuickJS</strong> A small JavaScript engine used as a sandbox for running user-supplied transformation functions. Isolated from the Node.js process — no network, filesystem, or module access.</p><p><strong>Message queue</strong> Hookshot&#39;s internal async event delivery system. Webhook events are placed on the queue and processed by Bridge.ts subscribers. Supports in-process delivery or Redis-backed queue for multi-worker setups.</p><p><strong>Widget</strong> A Matrix feature that allows embedding web UIs inside Matrix clients. Hookshot provides a widget for configuring connections without bot commands.</p><p><strong>Provisioning API</strong> Hookshot&#39;s REST API for managing connections programmatically. Available at <code>/widgetapi/v1/</code>. Used by the widget UI and available to external tools.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./what-is-hookshot">What is Hookshot</a> — System overview</li><li><a href="./event-lifecycle">Event Lifecycle</a> — How events flow</li><li><a href="./integration-model">Integration Model</a> — The Connection pattern</li><li><a href="./../architecture/connections">Architecture: Connections</a> — Deep dive</li></ul>',26)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
